CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE organizations(id uuid PRIMARY KEY,name text NOT NULL);
CREATE TABLE workspaces(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,UNIQUE(organization_id,id));
CREATE TABLE users(id uuid PRIMARY KEY,display_name text NOT NULL);
CREATE TABLE memberships(user_id uuid REFERENCES users(id),organization_id uuid REFERENCES organizations(id),workspace_id uuid NOT NULL,role text NOT NULL CHECK(role IN('ops','owner')),active boolean NOT NULL DEFAULT true,PRIMARY KEY(user_id,organization_id,workspace_id),FOREIGN KEY(organization_id,workspace_id)REFERENCES workspaces(organization_id,id));
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),organization_id uuid NOT NULL,workspace_id uuid NOT NULL,csrf text NOT NULL,expires_at timestamptz NOT NULL,FOREIGN KEY(user_id,organization_id,workspace_id)REFERENCES memberships(user_id,organization_id,workspace_id));
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,workspace_id uuid NOT NULL,title text NOT NULL CHECK(length(title) BETWEEN 1 AND 160),category text NOT NULL,description text NOT NULL DEFAULT '',source_refs text NOT NULL DEFAULT '',state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','pending','approved','exported')),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,id),FOREIGN KEY(organization_id,workspace_id)REFERENCES workspaces(organization_id,id));
CREATE TABLE skus(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,product_id uuid NOT NULL,seller_sku text NOT NULL,amount_minor integer NOT NULL CHECK(amount_minor>=0),currency text NOT NULL CHECK(currency IN('CNY','USD','EUR')),UNIQUE(organization_id,seller_sku),UNIQUE(organization_id,product_id),FOREIGN KEY(organization_id,product_id)REFERENCES products(organization_id,id));
CREATE TABLE approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,product_id uuid NOT NULL,product_version integer NOT NULL,digest text NOT NULL,requested_by uuid NOT NULL REFERENCES users(id),approved_by uuid REFERENCES users(id),state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','approved','rejected','invalidated')),version integer NOT NULL DEFAULT 1,expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',created_at timestamptz NOT NULL DEFAULT now(),CHECK(approved_by IS NULL OR approved_by<>requested_by),FOREIGN KEY(organization_id,product_id)REFERENCES products(organization_id,id));
CREATE TABLE audit_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,workspace_id uuid NOT NULL,actor_id uuid NOT NULL,action text NOT NULL,resource_id uuid,details jsonb NOT NULL DEFAULT '{}',trace_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency(organization_id uuid NOT NULL,actor_id uuid NOT NULL,action text NOT NULL,key text NOT NULL,digest text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,actor_id,action,key));
CREATE TABLE outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,aggregate_id uuid NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE publication_packages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,product_id uuid NOT NULL,approval_id uuid NOT NULL REFERENCES approvals(id),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,product_id)REFERENCES products(organization_id,id));
CREATE INDEX products_scope ON products(organization_id,workspace_id,created_at DESC,id DESC);
CREATE INDEX audit_scope ON audit_entries(organization_id,workspace_id,created_at DESC);
